#!/usr/bin/env bash
set -euo pipefail
encoded=''
printf '%s' "$encoded" > /tmp/wave30-materializer.sh.gz.b64
echo '952d719a1e3fb1e37e79dfd36f8cbe4683c18d54494a37540d68ca45f6e3c442  /tmp/wave30-materializer.sh.gz.b64' | sha256sum -c -
base64 -d /tmp/wave30-materializer.sh.gz.b64 | gzip -d > /tmp/wave30-materializer.sh
bash /tmp/wave30-materializer.sh
